        }, true);
        std::fs::write(&path, b"abcd").unwrap();
        let inner = Arc::new(crate::remote::transfer::FsTransferSink::new(
            root.path().to_path_buf(), root.path().to_path_buf(),
            crate::remote::transfer::FsSinkConfig { resume: true, ..Default::default() },
        ));
        let receiver = NeedListSink::new(
            inner, Arc::clone(&ledger),
            Some(ResumeRecv { resumed: Arc::new(AtomicU64::new(0)) }), None,
        );
        receiver.note_resume_baseline("file", ResumeBaseline::Hashed(
            crate::moved::Version::of(&std::fs::metadata(&path).unwrap())
